import { schemas } from '.'

/** Render the validator's schemas without maintaining a second grammar. */
export function renderSchemaReference(): string {
  return [
    '# Workflow and configuration schemas',
    '',
    '<!-- Generated by `pnpm --filter @pair/workflows schema:reference`. Do not edit by hand. -->',
    '',
    'These schemas come from the workflow validator.',
    '',
    '```json',
    JSON.stringify(schemas(), null, 2),
    '```',
    '',
  ].join('\n')
}
